  58(500): "DEFG-456789"  # to be redacted tag containing 500
}

li.t:
every Redacted Claim Hash has a corresponding Salted Disclosed Claim, and vice versa;
a Salted Disclosed Claim (disclosure) MAY contain additional Redacted Claim Keys nested inside the disclosure;
if any of the Redacted Claim Hashes are nested, the Holder follows the procedure in  (see also  for a worked example);

figure.sourcecode:
sd-cwt-issued = #6.18([ protected: bstr .cbor sd-protected, sd-unprotected, payload: bstr .cbor sd-payload, signature: bstr ])
sd-protected = { &(typ: 16) ^ => 293 / "application/sd-cwt", &(alg: 1) ^ => int, ? &(kid: 4) ^ => bstr, ? &(CWT_Claims: 15) ^ => issued_sd_cwt_map, ? &(sd_alg: 170) ^ => int, ; -16 for sha-256 ? &(sd_aead: 172) ^ => uint .size 2, * label => safe_value }
sd-unprotected = { ? &(sd_claims: 17) ^ => salted-array, ? &(sd_aead_encrypted_claims: 171) ^ => aead-encrypted-array, * label => safe_value }
sd-payload = { ; standard claims &(iss: 1) ^ => tstr, ; "https://issuer.example" ? &(sub: 2) ^ => tstr, ; "https://holder.example" ? &(aud: 3) ^ => tstr, ; "https://verifier.example/app" ? &(exp: 4) ^ => secs, ; 1883000000 ? &(nbf: 5) ^ => secs, ; 1683000000 ? &(iat: 6) ^ => secs, ; 1683000000 ? &(cti: 7) ^ => bstr, &(cnf: 8) ^ => safe_map, ; key confirmation ? &(vct: 11) ^ => bstr, ? &(cnonce: 39) ^ => bstr, ; ? redacted_claim_keys ^ => [ * bstr ], * label => issued_sd_cwt_value }

kbt-cwt = #6.18([ protected: bstr .cbor kbt-protected, kbt-unprotected, payload: bstr .cbor kbt-payload, signature: bstr ])
kbt-protected = { &(typ: 16) ^ => 294 / "application/kb+cwt", &(alg: 1) ^ => int, &(kcwt: 13) ^ => sd-cwt-issued, * label => safe_value }
kbt-unprotected = { * label => safe_value }
kbt-payload = { &(aud: 3) ^ => tstr, ; "https://verifier.example/app" time-or-cti-claims, ? &(cnonce: 39) ^ => bstr, * label => safe_value }
time-or-cti-claims = ( ; Requires either time claims that include an iat OR a cti claim. ; Note that in CDDL, the // operator has very low precedence (see ; Section 2.2.2 of RFC 8610) ; ; It is possible to have both a cti and time claims, but ; time-or-cti-claims insures at least cti or iat is present ? &(exp: 4) ^ => secs, ? &(nbf: 5) ^ => secs, &(iat: 6) ^ => secs // &(cti: 7) ^ => bstr )

{
